INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3501, 'Numbers 3:22', 'Numbers', 3, 22, '&nbsp;هغه ټول نران په شمېر کښې اووۀ زره او پينځۀ سوه کسان وُو چې عُمر يې يوه مياشت يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3502, 'Numbers 3:23', 'Numbers', 3, 23, '&nbsp;جيرسونيانو نمرپرېواتۀ طرف ته د مقدسې خېمې نه وروستو خېمې ودرولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3503, 'Numbers 3:24', 'Numbers', 3, 24, '&nbsp;د اِلياسف سره چې د لا‌اېل زوئ او د جيرسون قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3504, 'Numbers 3:25', 'Numbers', 3, 25, '&nbsp;هغوئ د مقدسې خېمې دنننۍ پړدې، پاسنۍ پړدې، د ننوتلو دروازې د پړدې د خيال ساتلو ذمه وار وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3505, 'Numbers 3:26', 'Numbers', 3, 26, '&nbsp;د هغه پړدو چې د خېمې د دربار او د قربان‌ګاه نه ګېرچاپېره وې او دربار ته د ننوتلو د دروازې پړدې. هغوئ د هغه ټول خِدمت ذمه وار وُو چې د دې څيزونو سره يې تعلق لرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3506, 'Numbers 3:27', 'Numbers', 3, 27, '&nbsp;عُمرام، اِضهار، حبرون او عُزى‌اېل څلور واړه خاندانه د قُهات د قبيلې نه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3507, 'Numbers 3:28', 'Numbers', 3, 28, '&nbsp;د هغه ټولو نرانو شمېر اتۀ زره او شپږ سوه کسان وُو چې د هغوئ عُمر يوه مياشت يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3508, 'Numbers 3:29', 'Numbers', 3, 29, '&nbsp;قُهاتيانو د مقدسې خېمې جنوبى طرف ته خېمې ودرولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3509, 'Numbers 3:30', 'Numbers', 3, 30, '&nbsp;د اليصفن سره چې د عُزى‌اېل زوئ او د قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3510, 'Numbers 3:31', 'Numbers', 3, 31, '&nbsp;د هغوئ ذمه وارى د دې څيزونو خيال ساتل وُو يعنې د لوظ صندوق، مېز، ډيوټ، قربان‌ګاه، د هغه لوښو چې اِمامان يې په مقدس ځائ کښې استعمالوى او زيات مقدس ځائ ته د ننوتلو پړده. هغوئ د هغه ټول خِدمت ذمه وار وُو چې د دې څيزونو سره يې تعلق لرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3511, 'Numbers 3:32', 'Numbers', 3, 32, '&nbsp;د ليويانو مشر د هارون اِمام زوئ اِلى‌عزر وو. د هغۀ مشرى په هغه کسانو باندې وه چې کومو په مقدس ځائ کښې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3512, 'Numbers 3:33', 'Numbers', 3, 33, '&nbsp;د محلى او موشى دواړه خاندانه د مرارى د قبيلې نه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3513, 'Numbers 3:34', 'Numbers', 3, 34, '&nbsp;د هغه ټولو نرانو شمېر شپږ زره او دوه سوه کسان وُو چې د هغوئ عُمر يوه مياشت يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3514, 'Numbers 3:35', 'Numbers', 3, 35, '&nbsp;مراريانو د مقدسې خېمې شمالى طرف ته خېمې ودرولې، د صورى‌اېل سره چې د ابى‌خېل زوئ او د قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3515, 'Numbers 3:36', 'Numbers', 3, 36, '&nbsp;هغوئ د مقدسې خېمې د چوکاټونو، دُرشلو، ستنو، پښو او د دې په نورو ټولو څيزونو ذمه وار مقرر شول. هغوئ د هغه ټول خِدمت ذمه وار وُو چې د دې څيزونو سره يې تعلق لرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3516, 'Numbers 3:37', 'Numbers', 3, 37, '&nbsp;هغوئ د ستنو، پښو، موږو او د دربار د بهرنۍ رسو د خيال ساتلو ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3517, 'Numbers 3:38', 'Numbers', 3, 38, '&nbsp;موسىٰ، هارون او د هغۀ زامنو نمرخاتۀ طرف ته د مقدسې خېمې په مخکښې خېمې ودرولې. هغوئ د هغه خِدمت ذمه وار وُو چې د بنى اِسرائيلو دپاره په مقدس ځائ کښې کېدلو. بل هر چا چې د دې د کولو کوشش کړے وے نو هغه به وژلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3518, 'Numbers 3:39', 'Numbers', 3, 39, '&nbsp;د مالِک خُدائ په حُکم باندې چې موسىٰ او هارون د ليويانو کوم شمېر وکړو هغه ټول نران دوويشت زره وُو چې د هغوئ عُمر يوه مياشت يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3519, 'Numbers 3:42', 'Numbers', 3, 42, '&nbsp;موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو او د بنى اِسرائيلو ټول مشران زامن يې وشمېرل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3520, 'Numbers 3:43', 'Numbers', 3, 43, '&nbsp;چې د هغوئ عُمر يوه مياشت يا د دې نه زيات وو، هغوئ ټول په شمېر کښې دوويشت زره دوه سوه او درې اويا کسان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3521, 'Numbers 3:44', 'Numbers', 3, 44, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3522, 'Numbers 3:45', 'Numbers', 3, 45, '&nbsp;”اوس د بنى اِسرائيلو د ټولو مشرانو زامنو په ځائ ليويان وقف کړه چې زما شى او د بنى اِسرائيلو د وړومبو پېدا شوو څاروو په ځائ د ليويانو څاروى وقف کړه. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3523, 'Numbers 3:46', 'Numbers', 3, 46, '&nbsp;خو د بنى اِسرائيلو مشران زامن د ليويانو نه دوه سوه او درې اويا کسان زيات دى، نو تۀ به هغه زيات زامن واپس اخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3524, 'Numbers 3:47', 'Numbers', 3, 47, '&nbsp;د هر يو دپاره د منلے شوى معيار په مطابق پينځۀ د سپينو زرو سيکې ورکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3525, 'Numbers 3:48', 'Numbers', 3, 48, '&nbsp;او دا پېسې هارون او د هغۀ زامنو ته ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3526, 'Numbers 3:51', 'Numbers', 3, 51, '&nbsp;او د مالِک خُدائ د فرمان په مطابق يې هغه هارون او د هغۀ زامنو له ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3527, 'Numbers 4:1', 'Numbers', 4, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3528, 'Numbers 4:2', 'Numbers', 4, 2, '&nbsp;”د ليويانو مردم‌شمارى وکړه چې هغوئ قُهاتيان دى. هغوئ دې قبيله په قبيله او خاندان په خاندان وشمېرلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3529, 'Numbers 4:3', 'Numbers', 4, 3, '&nbsp;او د هغه ټولو سړو نومونه دې وليکلے شى چې د هغوئ عُمر د دېرشو کالو نه تر پنځوسو کالو پورې وى او چې د مالِک خُدائ د حضور په مقدسه خېمه کښې کار کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3530, 'Numbers 4:4', 'Numbers', 4, 4, '&nbsp;د هغوئ خِدمت به د ډېرو مقدسو څيزونو خيال ساتل وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3531, 'Numbers 4:5', 'Numbers', 4, 5, '&nbsp;مالِک خُدائ موسىٰ ته دا اصُول وښودل. کله چې د کېمپ د وړلو وخت شى، نو هارون او د هغۀ زامن به مقدسې خېمې ته ننوځى، د لوظ د صندوق په مخکښې پړده به راکوزه کړى او د لوظ صندوق به ورباندې پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3532, 'Numbers 4:6', 'Numbers', 4, 6, '&nbsp;هغوئ به په دې باندې د څرمنې يوه ښۀ ټوټه واچوى، د آسمانى رنګ کپړه به دپاسه ورباندې خوره کړى او د وړلو دپاره به بازوګان وردننه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3533, 'Numbers 4:7', 'Numbers', 4, 7, '&nbsp;هغوئ به په مېز باندې د آسمانى رنګ کپړه خوره کړى چې په کوم مېز باندې د مالِک خُدائ روټۍ وى او په دې به لوښى، د خوشبويۍ جامونه، د نذرانو جامونه او د څښلو نذرانو دپاره منګى کېږدى. په مېز به همېشه روټۍ پرته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3534, 'Numbers 4:8', 'Numbers', 4, 8, '&nbsp;هغوئ به په دې هر څۀ باندې يوه سره کپړه خوره کړى، د څرمنې يوه ښۀ ټوټه دې ورباندې واچوى او د وړلو دپاره به بازوګان وردننه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3535, 'Numbers 4:9', 'Numbers', 4, 9, '&nbsp;هغوئ به د آسمانى رنګ يوه کپړه واخلى او ډيوټ، ډيوې، سرپوښونه، مجمعې او د زيتُونو تېلو ټول لوښى به ورباندې پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3536, 'Numbers 4:10', 'Numbers', 4, 10, '&nbsp;هغوئ به دا او د دې ټول څيزونه د څرمنې په يوه ښۀ ټوټه کښې تاو کړى او په وړُونکى چوکاټ به يې کېږدى چې په کوم باندې وړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3537, 'Numbers 4:11', 'Numbers', 4, 11, '&nbsp;بيا به هغوئ د سرو زرو په قربان‌ګاه باندې د آسمانى رنګ کپړه خوره کړى، د څرمنې يوه ښۀ ټوټه به ورباندې واچوى او د وړلو دپاره بازوګان به وردننه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3538, 'Numbers 4:12', 'Numbers', 4, 12, '&nbsp;هغوئ به په مقدس ځائ کښې هغه ټول لوښى واخلى چې په خِدمت کښې استعماليږى، د آسمانى رنګ په يوه کپړه کښې به يې تاو کړى، د څرمنې يوه ښۀ ټوټه به پرې واچوى او په وړُونکى چوکاټ باندې به يې کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3539, 'Numbers 4:13', 'Numbers', 4, 13, '&nbsp;هغوئ به د قربان‌ګاه نه ايره لرې کړى او په قربان‌ګاه به د کاسنى رنګ کپړه خوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3540, 'Numbers 4:14', 'Numbers', 4, 14, '&nbsp;هغوئ به په دې باندې هغه ټول سامان کېږدى چې د قربان‌ګاه په خِدمت کښې استعماليږى. لکه د اور لوښى، د غوښې دپاره درې غاښۍ، بېلچې او ښانکونه. بيا به هغوئ په دې باندې د څرمنې يوه ښۀ ټوټه واچوى، د وړلو دپاره به بازوګان وردننه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3541, 'Numbers 4:15', 'Numbers', 4, 15, '&nbsp;کله چې د خېمو د وړلو وخت راشى او هارون او د هغۀ زامن دا او د دې ټول سامان راونغاړى نو قُهاتيان به د مقدس سامان وړلو دپاره راشى. قُهاتيان به مقدس سامان له ګوتې نۀ وروړى، ګنې مړۀ به شى. دا هغه څيزونه دى چې د هغې د وړلو ذمه وارى د قُهاتيانو ده، په کوم وخت کښې چې مالِک خُدائ د حضور خېمه وړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3542, 'Numbers 4:16', 'Numbers', 4, 16, '&nbsp;د هارون اِمام زوئ اِلى‌عزر به د ټولې مقدسې خېمې او د ډيوو دپاره د تېلو، د خوشبويۍ، د غلې نذرانو، د غوړولو تېلو او په خېمه کښې د نورو ټولو څيزونو ذمه وار وى کوم چې مالِک خُدائ ته وقف شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3543, 'Numbers 4:17', 'Numbers', 4, 17, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3544, 'Numbers 4:18', 'Numbers', 4, 18, '&nbsp;”قُهاتيان مۀ پرېږدئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3545, 'Numbers 4:19', 'Numbers', 4, 19, '&nbsp;چې ډېرو مقدسو څيزونو ته نزدې راشى هسې نه چې مړۀ شى. د هغوئ د بچ کېدو د خاطره هارون او د هغۀ زامن به دننه ځى او هر سړى ته به خپل کار حواله کوى چې څۀ څيز به وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3546, 'Numbers 4:20', 'Numbers', 4, 20, '&nbsp;خو کۀ قُهاتيان مقدسې خېمې ته دننه لاړل او اِمامان يې وليدل چې د مقدسو څيزونو د وړلو تيارے کوى، نو دوئ به مړۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3547, 'Numbers 4:21', 'Numbers', 4, 21, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3548, 'Numbers 4:22', 'Numbers', 4, 22, '&nbsp;”د هغه ليويانو مردم‌شمارى وکړه چې جيرسونيان دى، هغوئ دې قبيله په قبيله او خاندان په خاندان وشمېرلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3549, 'Numbers 4:23', 'Numbers', 4, 23, '&nbsp;او د هغه ټولو سړو نومونه دې وليکلے شى چې عُمر يې د دېرشو کالو نه تر پنځوسو کالو پورې وى او چې د مالِک خُدائ د حضور په مقدسه خېمه کښې کار کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3550, 'Numbers 4:24', 'Numbers', 4, 24, '&nbsp;هغوئ به د دې سامان د وړلو ذمه وار وى يعنې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3551, 'Numbers 4:25', 'Numbers', 4, 25, '&nbsp;مقدسه خېمه، د دې دننه او بهر پړده، د دې دپاسه د ښې څرمنې ټوټه، د مقدسې خېمې پړده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3552, 'Numbers 4:26', 'Numbers', 4, 26, '&nbsp;د مقدسې خېمې او قربان‌ګاه نه ګېرچاپېره د دربار پړدې او رسۍ، دربار ته د ننوتلو د دروازې پړدې او هغه ټول سامان چې د دې په ودرولو کښې استعماليږى. هغوئ به هغه ټولې ذمه وارۍ سر ته رسوى چې د دې څيزونو سره تعلق لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3553, 'Numbers 4:27', 'Numbers', 4, 27, '&nbsp;موسىٰ او هارون به جيرسونيانو ته د خدمت کولو هدايت ورکوى او د هغوئ کارونه به ګورى چې هغه څۀ يې سر ته رسولې دى کۀ نه کوم چې هارون او د هغۀ زامنو ورته حواله کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3554, 'Numbers 4:28', 'Numbers', 4, 28, '&nbsp;په مقدسه خېمه کښې د جيرسونيانو ذمه وارۍ دا دى، هغوئ به دا د هارون اِمام زوئ اِتمر د ښودنې لاندې تر سره کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3555, 'Numbers 4:29', 'Numbers', 4, 29, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې، ”د هغه ليويانو مردم‌شمارى وکړه چې د مراريانو قبيلې دى، هغوئ قبيله په قبيله او خاندان په خاندان وشمېره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3556, 'Numbers 4:30', 'Numbers', 4, 30, '&nbsp;او د هغه ټولو سړو نومونه وليکه چې د هغوئ عُمر د دېرشو نه تر پنځوسو کالو پورې وى او چې د مالِک خُدائ د حضور په خېمه کښې کار کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3557, 'Numbers 4:31', 'Numbers', 4, 31, '&nbsp;هغوئ به د مقدسې خېمې د چوکاټونو، دُرشلو، ستنو او د پښو وړلو ذمه وار وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3558, 'Numbers 4:32', 'Numbers', 4, 32, '&nbsp;او د ستنو، پښو، موږو او د خېمې د ګېرچاپېره د دربار د پړدو رسو، سره د هغه ټول سامان د وړلو ذمه وار وى چې د دې په ودرولو کښې استعماليږى. هر يو سړے به د هغه څيزونو ذمه وار وى کوم چې ورته حواله شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3559, 'Numbers 4:33', 'Numbers', 4, 33, '&nbsp;دا د مراريانو د مقدسې خېمې د خِدمت ذمه وارۍ دى، هغوئ به د هارون اِمام زوئ اِتمر د ښودنې لاندې دا کار تر سره کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3560, 'Numbers 4:49', 'Numbers', 4, 49, '&nbsp;هر يو سړے د هغه حُکم په مطابق وشمېرلے شو چې مالِک خُدائ موسىٰ ته کړے وو، او د هغه حُکم په مطابق چې مالِک خُدائ موسىٰ له ورکړے وو نو هر يو ته د وړلو او خِدمت کولو ذمه وارۍ حواله شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3561, 'Numbers 5:1', 'Numbers', 5, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3562, 'Numbers 5:2', 'Numbers', 5, 2, '&nbsp;”بنى اِسرائيلو له حُکم ورکړه چې هر هغه څوک چې د جذام بيمارى لرى يا يې د بدن د يو ځائ نه اوبۀ ځى او هر څوک چې د مړى سره د لګېدلو په وجه ناپاک شوے وى نو هغوئ دې هغه د خېمو نه وشړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3563, 'Numbers 5:3', 'Numbers', 5, 3, '&nbsp;نر يا ښځه چې ناپاکه وى نو هغوئ بهر ولېږه، چې خېمې پليتې نۀ کړى، چرته چې زۀ د خپلو خلقو په مينځ کښې اوسېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3564, 'Numbers 5:4', 'Numbers', 5, 4, '&nbsp;بنى اِسرائيلو هم هغه شان وکړل او داسې خلق يې د خېمو نه بهر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3565, 'Numbers 5:5', 'Numbers', 5, 5, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3566, 'Numbers 5:6', 'Numbers', 5, 6, '&nbsp;”بنى اِسرائيلو ته دا اصُول وښايه. کله چې يو نر يا ښځه د چا خِلاف جرم وکړى نو هغه د مالِک خُدائ نافرمانى کوى نو هغه کس به قصوروار وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3567, 'Numbers 5:7', 'Numbers', 5, 7, '&nbsp;هغه دې خامخا د خپلې ګناه اِقرار وکړى او چې د چا خِلاف يې جرم کړے وى نو هغه کس له دې پوره تاوان ورکړى او شل فيصده دې زيات هم ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3568, 'Numbers 5:8', 'Numbers', 5, 8, '&nbsp;کۀ د مظلوم کس نزدې خپلوان نۀ وى چې د جرم تاوان ورته مِلاو شى، نو د جرم تاوان به د مالِک خُدائ په نوم اِمام له ورکړے شى، د دې سره به د مجرم د کفارې دپاره يو ګډ هم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3569, 'Numbers 5:9', 'Numbers', 5, 9, '&nbsp;اِسرائيليان چې هره يوه خاص برخه مالِک خُدائ ته پېش کوى نو هغه به د اِمام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3570, 'Numbers 5:10', 'Numbers', 5, 10, '&nbsp;هر يو اِمام هغه ټولې نذرانې د ځان دپاره ساتلے شى چې کومې هغوئ ته ورکړے شوې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3571, 'Numbers 5:11', 'Numbers', 5, 11, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3572, 'Numbers 5:15', 'Numbers', 5, 15, '&nbsp;په داسې دواړو حالتونو کښې سړے به خپله ښځه اِمام له بوځى. هغه به يو کلو د اوربشو اوړۀ هم يوسى، خو هغه به په دې باندې د زيتُونو تېل نۀ اچوى او نۀ به ورباندې خوشبوئى اچوى، ځکه چې دا نذرانه د شکمن خاوند د طرف نه ده، دا د دې دپاره پېش کيږى چې حقيقت څرګند شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3573, 'Numbers 5:16', 'Numbers', 5, 16, '&nbsp;اِمام به هغه ښځه وړاندې راولى او د مالِک خُدائ د قربان‌ګاه په مخکښې به يې ودروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3574, 'Numbers 5:17', 'Numbers', 5, 17, '&nbsp;هغه به په کنډول کښې څۀ مقدسې اوبۀ واچوى او د مالِک خُدائ د حضور مقدسې خېمې د دربار نه به لږه خاوره واخلى او په اوبو کښې به يې واچوى چې ترخې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3575, 'Numbers 5:18', 'Numbers', 5, 18, '&nbsp;بيا به هغه د ښځې وېښتۀ خوارۀ کړى او د اوړو نذرانه به د هغې په لاس کښې کېږدى. اِمام به هغه جام په خپلو لاسونو کښې ونيسى چې ترخې اوبۀ په کښې دى. دا د دې دپاره چې په هغه کس باندې لعنت راولى چې کوم ګناهګار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3576, 'Numbers 5:19', 'Numbers', 5, 19, '&nbsp;بيا به اِمام هغه ښځه دې ته راضى کړى چې داسې قسم وخورى، ”کۀ تا زنا کړې نۀ وى، نو چې دا اوبۀ کوم لعنت راولى نو هغه به تا ته نقصان نۀ رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3577, 'Numbers 5:20', 'Numbers', 5, 20, '&nbsp;خو کۀ تا زنا کړې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3578, 'Numbers 5:21', 'Numbers', 5, 21, '&nbsp;نو مالِک خُدائ دې ستا نوم ستا په خلقو کښې لعنتى کړى. تا دې شنډه کړى او ستا خېټه دې وپړسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3579, 'Numbers 5:22', 'Numbers', 5, 22, '&nbsp;دا اوبۀ به ستا خېټې ته ننوځى او ستا خېټه دې وپړسوى او تا دې شنډه کړى.“ نو ښځه به په جواب کښې داسې ووائى، ”آمين. هم داسې دې وشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3580, 'Numbers 5:23', 'Numbers', 5, 23, '&nbsp;بيا به اِمام دا لعنت په يو طومار وليکى او دا ليکل به د ترخو اوبو په جام کښې ووينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3581, 'Numbers 5:24', 'Numbers', 5, 24, '&nbsp;د هغې نه مخکښې چې په ښځه باندې دا اوبۀ وڅښى، کوم چې سخت درد راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3582, 'Numbers 5:25', 'Numbers', 5, 25, '&nbsp;اِمام به د ښځې د لاسونو نه د اوړو د شک نذرانه واخلى، مالِک خُدائ ته وقف کولو دپاره به يې پورته کړى او په قربان‌ګاه باندې به يې پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3583, 'Numbers 5:26', 'Numbers', 5, 26, '&nbsp;بيا به اِمام د دې نه يو موټے واخلى، دا به د نذرانې د يوې نښې په شان وى او په قربان‌ګاه باندې به يې وسوزوى. په آخر کښې به هغه په ښځه باندې اوبۀ وڅښوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3584, 'Numbers 5:27', 'Numbers', 5, 27, '&nbsp;کۀ هغې زنا کړې وى، نو اوبۀ به په هغې باندې سخت درد راولى، د هغې خېټه به وپړسيږى او هغه به شنډه شى. او د هغې نوم به په خپلو خلقو کښې لعنتى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3585, 'Numbers 5:28', 'Numbers', 5, 28, '&nbsp;خو کۀ هغه بې‌ګناه وى، نو نقصان به ورته نۀ رسيږى او د هغې به بچى پېدا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3586, 'Numbers 5:31', 'Numbers', 5, 31, '&nbsp;خاوند به د ګناه نه خلاص وى، خو کۀ ښځه ګناهګاره وى، نو هغې ته به خامخا د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3587, 'Numbers 6:1', 'Numbers', 6, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3588, 'Numbers 6:2', 'Numbers', 6, 2, '&nbsp;چې بنى اِسرائيلو ته دا اصُول وښائى. کۀ يو سړے يا ښځه د خاص مقصد دپاره د خپل ځان د نذير په حيثيت وقف کولو قسم وکړى او خپل ځان مالِک خُدائ ته وقف کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3589, 'Numbers 6:3', 'Numbers', 6, 3, '&nbsp;نو هغوئ به د ميو نه او شرابو نه ځان وساتى. هغوئ به داسې يو قِسم رس هم نۀ څښى چې د انګورو نه جوړ وى او نۀ به کچه انګور او نۀ اوچ انګور خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3590, 'Numbers 6:4', 'Numbers', 6, 4, '&nbsp;چې تر کومې پورې هغوئ د نذير په حيثيت وقف شوى وى، نو هغوئ به داسې يو څيز هم نۀ خورى چې د انګورو د باغ نه راځى، د انګورو پوستکے يا تخم به هم نۀ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3591, 'Numbers 6:5', 'Numbers', 6, 5, '&nbsp;چې تر کومې پورې هغوئ د نذير په حيثيت د قسم لاندې وى، نو وېښتۀ به نۀ واړۀ کوى. ترڅو چې د هغوئ د قسم نيټه پوره شوې نۀ وى، هغوئ مالِک خُدائ ته وقف دى او وېښتۀ به پرېږدى چې لوئ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3592, 'Numbers 6:8', 'Numbers', 6, 8, '&nbsp;چې تر کومې پورې هغوئ د نذير په حيثيت د قسم لاندې وى، نو هغوئ مالِک خُدائ ته وقف دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3593, 'Numbers 6:9', 'Numbers', 6, 9, '&nbsp;کۀ د هغۀ وقف شوى وېښتۀ داسې ناپاک شى چې هغه د يو داسې کس په خوا کښې وى چې ناڅاپه مړ شى، نو هغه به خامخا اووۀ ورځې اِنتظار وکړى او بيا به خپل وېښتۀ کل کړى، او هغه به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3594, 'Numbers 6:10', 'Numbers', 6, 10, '&nbsp;په اتمه ورځ به هغوئ دوه ګوګوشتکې يا دوه کونترې د مالِک خُدائ د حضور مقدسې خېمې په دروازه کښې اِمام له راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3595, 'Numbers 6:11', 'Numbers', 6, 11, '&nbsp;اِمام به يوه د ګناه د نذرانې په توګه پېش کړى او بله د سوزېدونکې نذرانې په توګه او د هغوئ دپاره به کفاره ادا کړى ځکه چې هغوئ مړى ته د نزدې کېدو په وجه ګناه کړې ده. هم په هغه ورځ به د هغوئ وېښتۀ بيا پاک شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3596, 'Numbers 6:12', 'Numbers', 6, 12, '&nbsp;او خپل وخت به مالِک خُدائ ته د نذير په حيثيت وقف کړى. تېر شوے وخت نۀ حسابيږى، ځکه چې د هغوئ وقف شوى وېښتۀ ناپاک شوى وُو. د ګناه د تاوان د نذرانې دپاره به هغوئ د يو کال ګډُورے راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3597, 'Numbers 6:13', 'Numbers', 6, 13, '&nbsp;د قانون په مطابق کله چې هغه کس د نذير په حيثيت خپل قسم پوره کړى، نو هغوئ به دا رسم ادا کوى. هغوئ به د مقدسې خېمې دروازې ته ورشى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3598, 'Numbers 6:14', 'Numbers', 6, 14, '&nbsp;او مالِک خُدائ ته دې درې داسې ځناور قربانى کړى چې هيڅ عېب په کښې نۀ وى، د سوزېدونکې نذرانې دپاره يو کلن ګډُورے، يوه کلنه ګډورۍ د ګناه نذرانې دپاره او د سلامتۍ نذرانې دپاره يو ګډ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3599, 'Numbers 6:15', 'Numbers', 6, 15, '&nbsp;هغوئ به د پتيرې روټۍ يوه ډکه ټوکرۍ هم پېش کړى، د اوړو ډبلې روټۍ چې د زيتُونو تېل په کښې ګډ وى او نرۍ نرۍ روټۍ چې د زيتُونو تېل ورباندې لګولے شوى وى او د دې نه علاوه د غلې او د څښلو نذرانې به هم ورسره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3600, 'Numbers 6:16', 'Numbers', 6, 16, '&nbsp;اِمام به دا ټولې مالِک خُدائ ته حاضرې کړى او د ګناه نذرانه او سوزېدونکې نذرانه به پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');